/// <param name = "_RefRecIdNDXPrivilegeTable">RefRecId</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXRole2PrivilegeTable</returns>
static NDXRole2PrivilegeTable find(RefRecId _RefRecIdNDXRoleTable, RefRecId _RefRecIdNDXPrivilegeTable, boolean _forUpdate = true)
{
    NDXRole2PrivilegeTable nDXRole2PrivilegeTable;
    nDXRole2PrivilegeTable.selectForUpdate(_forUpdate);
    select nDXRole2PrivilegeTable
        where nDXRole2PrivilegeTable.RefRecIdNDXRoleTable == _RefRecIdNDXRoleTable
        &&  nDXRole2PrivilegeTable.RefRecIdNDXPrivilegeTable == _RefRecIdNDXPrivilegeTable;
    return nDXRole2PrivilegeTable;
}

