static NDXRole2PrivilegeTable findOrCreate(RefRecId _RefRecIdNDXRoleTable, RefRecId _RefRecIdNDXPrivilegeTable, boolean _insert = true)
{
    NDXRole2PrivilegeTable nDXRole2PrivilegeTable;
