            nDXRole2PrivilegeTable.insert();
        }
    }
    return nDXRole2PrivilegeTable;
}

/// <summary>
/// PaffH 20.01.21
/// delete records not updated
/// </summary>
/// <param name = "_updatedUtcDateTime">NDXUpdatedUTCDateTime</param>
/// <param name = "_logger">NDXLoggerSecurityInformationClass</param>
/// <returns>counter deleted records</returns>
static public int deleteNotUpdated(NDXUpdatedUTCDateTime _updatedUtcDateTime, NDXLoggerSecurityInformationClass _logger)
{
    NDXRole2PrivilegeTable nDXRole2PrivilegeTable;

    NDXArgsLoggerSecuritiyInformation argsLogger = new NDXArgsLoggerSecuritiyInformation();
    argsLogger.parmLogActivity(strFmt("@NDX:NDXDeleteRecordsInTable", tableId2PName(nDXRole2PrivilegeTable.TableId)));
    _logger.LogLineCreate(argsLogger);

    NDXHelperTable::skipForDelete(nDXRole2PrivilegeTable);
    delete_from nDXRole2PrivilegeTable
        where nDXRole2PrivilegeTable.UpdatedUTCDateTime != _updatedUtcDateTime;

    argsLogger.parmCounter(int642int(nDXRole2PrivilegeTable.RowCount()));
    _logger.LogLineChange(argsLogger);

    return int642int(nDXRole2PrivilegeTable.RowCount());
}
